    pl,ph=struct.unpack('<HH',d[off:off+4]); off+=9
    plen=ph
    print('pat',p,'packlen',pl,'type',ph)
    raw=d[off:off+pl]
    # manual depack
    nch=8
    pos=0; rows=[]
    row=[]; 
    while pos<len(raw):
        b=raw[pos]; pos+=1
        if b==0x80:
            while len(row)<nch*5: row.append(0)
            rows.append(row); row=[]
            continue
        cell=[0]*5
        if b&0x80:
            cell[0]=raw[pos]; pos+=1
        if b&0x40:
            cell[1]=raw[pos]; pos+=1
        if b&0x20:
            cell[2]=raw[pos]; pos+=1
        if b&0x10:
            cell[3]=raw[pos]; pos+=1
        if b&0x01:
            cell[4]=raw[pos]; pos+=1
        row+=cell
        if len(row)==nch*5:
            rows.append(row); row=[]
    if row: 
        while len(row)<nch*5: row.append(0)
        rows.append(row)
    print(' rows depacked:',len(rows))
    for r in rows[:4]:
        print('  ', [r[i*5:i*5+5].hex(' ') for i in range(nch)])
    off+=pl
EOF"}

