{"command":"cd /workspace && python3 - <<'PYEOF'
import struct, itertools
d=open('/tmp/pt.xm','rb').read()
ph=336
plen,ptype,rows,psize=struct.unpack('<I B H H',d[ph:ph+9])
data=d[ph+9:ph+9+psize]
# Brute force bit assignment. Known cells:
# (row,ch) -> dict of expected values
known = {
 (0,0): dict(note=49,ins=1,vol=64),
 (4,1): dict(note=53,ins=1,vol=50,eff=12,effp=64),
 (8,2): dict(note=97,ins=1,vol=0,eff=1,effp=32),
}
fields=['note','ins','vol','eff','effp']
for perm in itertools.permutations(fields):
    # bits: 0x01,0x02,0x04,0x08,0x10 assigned to perm order; 0x80 = ? maybe always set for non-empty
    bits=[0x01,0x02,0x04,0x08,0x10]
    # try: mask bit for field f = bits[perm.index(f)], plus 0x80 flag
    def dec():
        i=0; row=0; ch=0; out={}
        while i<len(data) and row<32:
            b=data[i]
            if b==0x80:
                i+=1; out[(row,ch)]=dict(note=0,ins=0,vol=0,eff=0,effp=0)
            else:
                if not (b&0x80): return None
                i+=1
                cell={}
                for f,bt in zip(perm,bits):
                    if b&bt:
                        if i>=len(data): return None
                        cell[f]=data[i]; i+=1
                    else:
                        cell[f]=0
                out[(row,ch)]=cell
            ch+=1
            if ch==8: ch=0; row+=1
        return out if i==len(data) and row==32 else None
    r=dec()
    if r is None: continue
    ok=True
    for k,v in known.items():
        for f,val in v.items():
            if r.get(k,{}).get(f)!=val: ok=False
    if ok:
        print('FOUND', perm)
        for k in sorted(known): print(k, r[k])
PYEOF"}

