# Now let's find the exact call that crashes. Test step by step with a fresh process each time
# by using a direct StdioMCP-like approach: run the binary and speak JSON-RPC.
import subprocess, json, threading, queue, time, os

class MCP:
    def __init__(self):
        env=dict(os.environ); env['SDL_AUDIODRIVER']='dummy'
        env['HOME']='/workspace/isolated-home'; env['XDG_CONFIG_HOME']='/workspace/isolated-home/.config'
        self.p=subprocess.Popen(['/usr/local/bin/ft2-clone','--mcp'],stdin=subprocess.PIPE,
                                stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,bufsize=1,env=env)
        self.q=queue.Queue()
        threading.Thread(target=self._r,daemon=True).start()
        threading.Thread(target=self._e,daemon=True).start()
        self.n=0
    def _r(self):
        for line in self.p.stdout:
            self.q.put(line)
    def _e(self):
        for line in self.p.stderr:
            print('STDERR:',line.strip())
    def call(self,name,args):
        self.n+=1
        msg=json.dumps({'jsonrpc':'2.0','id':self.n,'method':'tools/call','params':{'name':name,'arguments':args}})
        self.p.stdin.write(msg+'\n'); self.p.stdin.flush()
        try:
